using Arconist.Core;
using System.Text.Json;

string root=args.Length>0?args[0]:".";string evidence=args.Length>1?args[1]:"arc-evidence";Directory.CreateDirectory(evidence);
int passed=0,failed=0;var outcomes=new List<object>();
void Check(bool ok,string message){if(!ok)throw new Exception(message);}
void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e.Message);}}
string Load(string name)=>File.ReadAllText(Path.Combine(root,"reconstructed/godot/content",name));
string Aff(string body)=>"AudioOffset:0\nTimingPointDensityFactor:1.0\n-\ntiming(0,120.00,4.00);\n"+body;
const string ordinary="arc(1000,2000,0.20,0.80,s,0.50,0.50,0,none,false);";
Kernel New(string? text=null,int height=500){var k=new Kernel(Chart.Parse(text??Load("native_moving_arc.aff")),arcHeight:height);k.Frame(0);k.Frame(3002);return k;}
SkyContact At(ArcState a)=>new(new SkyPoint(a.TargetX,a.TargetY,0));
void F(Kernel k,int e)=>k.Frame(e+3002);
Test("typed AFF provenance, units and chart end",()=>{var a=Chart.Parse(Load("native_moving_arc.aff"));var n=a.Arcs.Single();Check(n.Start==1000&&n.End==2000&&n.X0==0.2f&&n.X1==0.8f&&n.Y0==0.5f&&n.Color==0&&n.Curve=="s"&&!n.Trace&&n.Effect=="none"&&n.Bpm==120&&n.Density==1&&n.Interval==250&&n.Checkpoints.SequenceEqual(new[]{1250,1500,1750})&&a.JudgmentUnits==3&&a.EndTime==2500,"construction");});
var invalid=new[]{ordinary.Replace(",s,",",b,"),ordinary.Replace(",s,",",si,"),ordinary.Replace("false","true"),ordinary.Replace("none","effect"),ordinary.Replace("2000","1000"),ordinary.Replace("0.20","NaN"),ordinary.Replace("0.20","-0.20"),ordinary.Replace("0.80","1.20"),ordinary.Replace("0.20","0"),ordinary.Replace(",0,none",",2,none"),ordinary.Replace(");",")[arctap(1500)];"),ordinary.Replace("false)","false,5.0)")};
for(int i=0;i<invalid.Length;i++){int index=i;Test("unsupported AFF rejection "+i,()=>{bool rejected=false;try{Chart.Parse(Aff(invalid[index]));}catch(Exception e)when(e is FormatException||e is NotSupportedException){rejected=true;}Check(rejected,"silently supported");});}
Test("crossing and linked layouts explicitly excluded",()=>{foreach(int start in new[]{1000,2000,2999}){bool rejected=false;try{Chart.Parse(Aff(ordinary+$"arc({start},{start+1000},0.80,0.20,s,0.50,0.50,1,none,false);"));}catch(NotSupportedException){rejected=true;}Check(rejected,"layout");}});
Test("native geometry H0 and prepared H500 distinct",()=>{var k=New(height:0);var g=k.Arcs[0].Geometry;Check(g.X0==-255&&g.X1==255&&g.Y0==50&&g.Y1==50&&g.Z==-8089&&g.Rate==7&&g.Samples.Count==9,"E028 samples");Check(g.Samples[^1].X==510&&g.Samples[^2].X==510&&g.Samples[^1].Z==-8089,"repeated endpoint");Check(New().Arcs[0].Geometry.Y0==300,"E009 environment");});
Test("sampling rate and geometry extra do not change checkpoints",()=>{var shortArc=New(Aff(ordinary.Replace("2000","1500"))).Arcs[0];Check(shortArc.Geometry.Rate==14,"short rate");var a=New(Aff(ordinary.Replace("false)","false,2.0)"))).Arcs[0];Check(a.Geometry.DetailSamples.Count>a.Geometry.Samples.Count&&a.Records.Count==3,"separate extra density");});
Test("E028 moving cache, ownership and exact recorder trace",()=>{
 var k=New(height:0);var a=k.Arcs[0];using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"reference_traces/r007/native-arc.json")));var rows=doc.RootElement.GetProperty("rows").EnumerateArray().ToDictionary(r=>r.GetProperty("e").GetInt32());var trace=new List<object>();var awards=new List<int>();string? first=null;
 try{foreach(int e in new[]{1000,1001,1125,1250,1300,1375,1500,1625,1750,1875}){
 F(k,e);awards.AddRange(k.Judgments.Select(j=>j.EffectiveTime));if(e==1000)k.DownSpatial(e+3002,42,0,At(a));else k.MoveSpatial(42,0,At(a));F(k,e);awards.AddRange(k.Judgments.Select(j=>j.EffectiveTime));double x=(double)a.Geometry.X0+a.Cache.X;trace.Add(new{e,x,k.Pure,k.Score,health=(double)k.Health,owner=a.Color.Owner,claimed=k.ClaimedIds,cache=a.Cache,records=a.Records});
 if(rows.TryGetValue(e,out var r)){Check(Math.Abs(x-r.GetProperty("x").GetDouble())<0.00006,$"E{e} cache X {x}");Check(k.Pure==r.GetProperty("pure").GetInt32()&&k.Score==r.GetProperty("score").GetInt32()&&(double)k.Health==r.GetProperty("health").GetDouble(),$"E{e} recorder");}Check(a.Holding&&a.Color.Owner==0&&k.ClaimedIds.SequenceEqual(new[]{0})&&k.Contacts.Single().Id==0,$"E{e} ownership");}
 Check(awards.SequenceEqual(new[]{1125,1375,1625})&&a.Records.All(r=>r.Resolved)&&k.Shining==3&&k.Far==0&&k.Lost==0,"unique recorder calls");k.Up(42);Check(a.Color.Owner==-1&&a.Color.ReleaseTime==1875&&k.ClaimedIds.Count==0&&k.ContactCount==0,"native UP");F(k,1876);Check(!a.Holding&&k.Result==null&&k.Score==10000003,"native stop boundary");}
 catch(Exception e){first=e.Message;throw;}
 finally{File.WriteAllText(Path.Combine(evidence,"E028-moving.json"),JsonSerializer.Serialize(new{authority="E028",firstDifference=first,trace,awards},new JsonSerializerOptions{WriteIndented=true}));}
});
Test("E009 prepared static complete result separate from E028",()=>{var k=new Kernel(Chart.Parse(Aff(ordinary.Replace("0.80","0.20"))),requestedSpeed:6,baseBpm:180);k.Frame(0);k.Frame(3002);var a=k.Arcs[0];F(k,999);Check(!a.CacheEnabled,"before start");k.DownSpatial(4001,42,0,new SkyContact(new SkyPoint(-255,300,0)));foreach(int e in new[]{1000,1125,1375,1625})F(k,e);Check(k.Pure==3&&k.Shining==3&&k.Score==10000003&&(double)k.Health==80.5999984741211,"native score health");F(k,2001);Check(!a.Active&&a.Color.Owner==0&&a.Color.ReleaseTime==-1,"end reset not owner erase");F(k,2501);Check(k.Result!.Category==3&&k.Result.Health==80,"native result");});
Test("cache precedes continuous activation; input never runs frame",()=>{var k=New();F(k,1000);var a=k.Arcs[0];k.DownSpatial(4002,42,0,At(a));Check(!a.Holding&&k.Pure==0,"DOWN activity");F(k,1125);Check(a.Holding&&k.Pure==1,"frame continuous");k.MoveSpatial(42,0,At(a));Check(k.LastFrameTime==1125&&k.Pure==1,"MOVE no frame");F(k,1125);Check(k.Pure==1&&k.Judgments.Count==0,"guard");});
Test("strict ordinary internal extent190 and Y truncation",()=>{SkyContact P(float x,float y=300,float z=0)=>new(new SkyPoint(x,y,z));Check(ArcSpatial.Matches(0,300,P(189.999f))&&!ArcSpatial.Matches(0,300,P(190))&&!ArcSpatial.Matches(0,300,P(-190)),"strict width");Check(!ArcSpatial.Matches(0,300,P(0,300,-1000))&&ArcSpatial.Matches(0,300,P(0,-50)),"depth and upstream clamp");Check(!ArcSpatial.Matches(0,300,P(float.NaN))&&!ArcSpatial.Matches(float.NaN,300,P(0)),"finite");Check(ArcSpatial.Scale(-1,720)==2&&ArcSpatial.Scale(900,960)==1.125f,"viewport scale");});
Test("region exit retains owner and same identity reentry",()=>{var k=New();F(k,1000);var a=k.Arcs[0];k.DownSpatial(4002,42,0,At(a));F(k,1001);k.MoveSpatial(42,0,new SkyContact(new SkyPoint(9000,300,0)));F(k,1100);Check(!a.Holding&&a.Color.Owner==0&&k.ContactCount==1,"outside ownership");k.MoveSpatial(42,0,At(a));F(k,1100);Check(a.Holding&&k.Contacts.Single().Id==0,"same ID reentry");});
Test("foreign contact cannot steal established owner",()=>{var k=New();F(k,1000);var a=k.Arcs[0];k.DownSpatial(4002,42,0,At(a));F(k,1001);k.DownSpatial(4003,43,0,At(a));k.MoveSpatial(42,0,null);F(k,1002);Check(!a.Holding&&a.Color.Owner==0&&k.Contacts.Count==2,"foreign reject");});
Test("E009 recorded release blocks2199 accepts2200",()=>{var k=New(Aff("arc(1000,4000,0.20,0.20,s,0.50,0.50,0,none,false);"));var a=k.Arcs[0];F(k,1000);k.DownSpatial(4002,42,0,At(a));F(k,1125);F(k,1200);k.Up(42);Check(a.Color.ReleaseTime==1200,"release anchor");F(k,2199);k.DownSpatial(5201,43,0,At(a));F(k,2199);Check(!a.Holding&&k.Pure==1&&k.Lost==1&&a.Color.Owner==-1,"below native boundary");F(k,2200);Check(a.Holding&&a.Color.Owner==1&&k.Pure==4&&k.Lost==1,"equality accepts");});
Test("CANCEL removes contact claimed vector and owner",()=>{var k=New();F(k,1000);var a=k.Arcs[0];k.DownSpatial(4002,42,0,At(a));F(k,1001);k.Cancel(42);Check(k.ContactCount==0&&k.ClaimedIds.Count==0&&a.Color.Owner==-1&&a.Color.ReleaseTime==1001,"CANCEL");F(k,1002);Check(!a.Holding&&k.Pure==0,"no award");});
Test("temporally separated arcs share mapped color object",()=>{var k=New(Aff(ordinary+ordinary.Replace("1000,2000","4000,5000")));Check(ReferenceEquals(k.Arcs[0].Color,k.Arcs[1].Color),"shared LogicColor");});
Test("inactive overdue2249/2250 and derived2HP",()=>{var k=New(Aff(ordinary.Replace("0.80","0.20")));F(k,1000);var a=k.Arcs[0];k.DownSpatial(4002,42,0,At(a));F(k,1125);F(k,1375);k.Up(42);F(k,2249);Check(k.Pure==2&&k.Lost==0&&!a.Records[2].Resolved,"2249");float h=k.Health;F(k,2250);Check(k.Lost==1&&a.Records[2].Resolved&&k.Health==h-2f,"2250 damage");F(k,2250);Check(k.Lost==1&&k.Judgments.Count==0,"miss guard");});
Test("arc pause60seconds preserves cache owner and records",()=>{var k=New(Aff(ordinary.Replace("0.80","0.20")));F(k,1000);var a=k.Arcs[0];k.DownSpatial(4002,42,0,At(a));F(k,1125);k.Pause(4202);var cache=a.Cache;F(k,61200);Check(k.Timeline.EffectiveTime==1200&&a.Cache.X==cache.X&&a.Color.Owner==0&&!a.Holding&&k.Pure==1,"frozen");k.DownSpatial(64202,43,0,At(a));Check(k.ContactCount==1,"paused gate");k.Resume(64202);foreach(int e in new[]{1201,1375,1625,2501})k.Frame(e+63002);Check(k.Pure==3&&k.Lost==0&&k.Score==10000003&&k.Result!=null,"retained resume");});
Test("paused UP cleanup cannot resurrect old owner",()=>{var k=New();F(k,1000);var a=k.Arcs[0];k.DownSpatial(4002,42,0,At(a));F(k,1001);k.Pause(4102);k.Up(42);Check(a.Color.Owner==-1&&k.Contacts.Count==0,"paused UP");k.Resume(64102);k.Frame(64103);Check(!a.Holding&&k.ContactCount==0,"no ghost");});
Test("timing change inside arc rejected",()=>{bool rejected=false;try{Chart.Parse(Aff(ordinary+"timing(1500,180.00,4.00);"));}catch(NotSupportedException){rejected=true;}Check(rejected,"unsupported timing");});
Test("complete moving mixed chart and fresh replay",()=>{var k=New(Load("sky_practice.aff"));Check(k.Chart.JudgmentUnits==35&&k.Chart.EndTime==14620,"N/end");for(int e=1;e<=14621;e++){F(k,e);foreach(var t in k.Chart.Taps.Where(t=>t.Time==e)){k.Down(e+3002,200+t.Ordinal,t.Lane);k.Up(200+t.Ordinal);}var a=k.Arcs[0];if(e==a.Start)k.DownSpatial(e+3002,42,0,At(a));else if(e>a.Start&&e<=a.End)k.MoveSpatial(42,0,At(a));if(e==a.End+1)k.Up(42);}Check(k.Result!.Score==10000035&&k.Pure==35&&k.Lost==0&&k.MaxCombo==35,"integrated moving result");var fresh=New(Load("sky_practice.aff"));Check(fresh.ContactCount==0&&fresh.Arcs[0].Color.Owner==-1&&fresh.Arcs[0].Records.All(r=>!r.Resolved),"restart");});
Test("stale fixed point negative is engineering integration",()=>{var k=New(Load("sky_practice.aff"));F(k,4000);var a=k.Arcs[0];k.DownSpatial(7002,42,0,At(a));for(int e=4001;e<=14621;e++)F(k,e);Check(k.Pure<31&&k.Lost>0,"wide trajectory requires movement");});
File.WriteAllText(Path.Combine(evidence,"core-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R007 core: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");return failed==0?0:1;
